script:
// Settings. On a desktop it is a dialog that opens over the current page (from
// the logo menu's "Settings", or ?settings=account|publications in the
// address). On a phone it is the /settings page, which this script also runs:
// its tabs. Every page loads this script. Needs ui.js and shell.js. Saved
// posts live on the Manage all posts page (posts.js), not here.
;(function () {
	'use strict'

	var CAFE = (window.CAFE = window.CAFE || {})
	var ICONS = {"newspaper": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M4 22h16a2 2 0 0 0 2-2V4a2 2 0 0 0-2-2H8a2 2 0 0 0-2 2v16a2 2 0 0 1-2 2Zm0 0a2 2 0 0 1-2-2v-9c0-1.1.9-2 2-2h2\" />\n  <path d=\"M18 14h-8\" />\n  <path d=\"M15 18h-5\" />\n  <path d=\"M10 6h8v4h-8V6Z\" /></svg>", "plus": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M5 12h14\" />\n  <path d=\"M12 5v14\" /></svg>"}
	var DESKTOP = window.matchMedia('(min-width: 768px)')
	// Keep this in sync with blocks.PUBLICATIONS_ENABLED (generate.py) - the
	// mobile page already skips its Publications blocks there; this is the
	// matching switch for the desktop dialog, which is built entirely here.
	var PUBLICATIONS_ENABLED = false
	var TABS = PUBLICATIONS_ENABLED ? ['account', 'publications'] : ['account']
	var TITLES = { account: 'Account', publications: 'Publications' }

	var el = function (tag, className, text) {
		return CAFE.el(tag, className, text)
	}

	function icon(name) {
		var holder = document.createElement('span')
		holder.className = 'cafe-set-icon'
		holder.innerHTML = ICONS[name] || ''
		return holder
	}

	// The part of the email before the "@": what the old app shows as the username.
	function currentUser() {
		var match = document.cookie.match(/(?:^|;\s*)user_id=([^;]*)/)
		var user = match ? decodeURIComponent(match[1]) : ''
		return user && user !== 'Guest' ? user : ''
	}

	// ---- Publications (which the account is a member of, not subscribed to) ----

	function leavePublication(pub, panel) {
		CAFE.confirm({
			title: 'Leave this publication?',
			message: "You'll need a new invitation to rejoin " + (pub.title || pub.publication) + '.',
			confirmLabel: 'Leave',
			danger: true,
		}).then(function (ok) {
			if (!ok) return
			CAFE.api('cafe.api.leave_publication', { handle: pub.publication }).then(function () {
				loadPublications(panel)
			}, errorToast)
		})
	}

	function publicationRow(pub, first, panel) {
		var row = el('div', 'cafe-set-row' + (first ? ' first' : ''))
		var text = el('div', 'cafe-set-row-text')
		var link = el('a', 'cafe-set-row-title', pub.title || pub.publication)
		link.href = '/publications/' + encodeURIComponent(pub.publication)
		text.appendChild(link)
		text.appendChild(el('div', 'cafe-set-row-role', pub.role))
		row.appendChild(text)
		var leave = el('button', 'cafe-set-button leave', 'Leave')
		leave.type = 'button'
		leave.addEventListener('click', function () {
			leavePublication(pub, panel)
		})
		row.appendChild(leave)
		return row
	}

	function errorToast(error) {
		CAFE.toast(error.message || CAFE.DEFAULT_ERROR, 'error')
	}

	function openCreatePublication(panel) {
		CAFE.form({
			title: 'Create a new publication',
			persistKey: 'create-publication',
			submitLabel: 'Create',
			values: {},
			fields: [
				{ name: 'title', label: 'Name', required: true, maxLength: 140 },
				{ name: 'handle', label: 'Handle', required: true, maxLength: 140 },
			],
			onSubmit: function (values) {
				return CAFE.api('cafe.api.create_publication', values).then(function () {
					loadPublications(panel)
				})
			},
		})
	}

	// Fills `panel` the same way loadSaved fills the Saved one: .cafe-loading,
	// .cafe-pub-mem-empty, .cafe-pub-mem-error and .cafe-pub-mem-list - its
	// own class names, not the Saved panel's, since both can be on screen
	// (as hidden panels) at once and querying by a shared name would find
	// whichever panel happens to come first in the DOM.
	var pubRequest = 0
	function loadPublications(panel) {
		var loading = panel.querySelector('.cafe-loading')
		var empty = panel.querySelector('.cafe-pub-mem-empty')
		var failed = panel.querySelector('.cafe-pub-mem-error')
		var list = panel.querySelector('.cafe-pub-mem-list')
		var request = ++pubRequest

		list.replaceChildren()
		empty.hidden = true
		failed.hidden = true
		loading.hidden = false
		CAFE.get('cafe.api.list_my_publications').then(
			function (data) {
				if (request !== pubRequest) return
				loading.hidden = true
				var rows = data || []
				empty.hidden = rows.length > 0
				rows.forEach(function (pub, index) {
					list.appendChild(publicationRow(pub, index === 0, panel))
				})
			},
			function () {
				if (request !== pubRequest) return
				loading.hidden = true
				failed.hidden = false
			}
		)
	}

	// ---- The page (phones) ----

	function setupPage(root) {
		var buttons = root.querySelectorAll('.cafe-tab-btn')
		var account = document.getElementById('cafe-settings-account')
		// Only in the DOM at all when PUBLICATIONS_ENABLED was true at generate
		// time (settings_page.py) - null here otherwise.
		var publications = document.getElementById('cafe-settings-publications')

		function show(tab, updateAddress) {
			buttons.forEach(function (button) {
				button.setAttribute('aria-selected', button.getAttribute('data-tab') === tab ? 'true' : 'false')
			})
			account.hidden = tab !== 'account'
			if (publications) publications.hidden = tab !== 'publications'
			if (tab === 'publications' && publications) loadPublications(publications)
			if (updateAddress) {
				var url = new URL(location.href)
				if (tab === 'account') url.searchParams.delete('tab')
				else url.searchParams.set('tab', tab)
				history.replaceState(null, '', url)
			}
		}

		root.addEventListener('click', function (event) {
			var button = event.target.closest('.cafe-tab-btn')
			if (button) show(button.getAttribute('data-tab'), true)
		})
		document.getElementById('cafe-settings-logout').addEventListener('click', function () {
			CAFE.confirmLogout()
		})
		var createButton = document.getElementById('cafe-settings-pub-create')
		if (createButton) {
			createButton.addEventListener('click', function () {
				openCreatePublication(publications)
			})
		}
		var wantedTab = new URLSearchParams(location.search).get('tab')
		show(TABS.indexOf(wantedTab) >= 0 ? wantedTab : 'account', false)
	}

	// ---- The dialog (desktops) ----

	var dialog = null

	function accountRow(title, description, control, first) {
		var row = el('div', 'cafe-set-row' + (first ? ' first' : ''))
		var text = el('div', 'cafe-set-row-text')
		text.appendChild(el('div', 'cafe-set-row-title', title))
		if (description) text.appendChild(el('div', 'cafe-set-row-desc', description))
		row.appendChild(text)
		row.appendChild(control)
		return row
	}

	function buildAccount(close) {
		var user = currentUser()
		var box = el('div', 'cafe-set-rows')
		box.appendChild(accountRow('Username', '', el('span', 'cafe-set-value', '@' + user.split('@')[0]), true))
		box.appendChild(accountRow('Email address', '', el('span', 'cafe-set-value', user)))
		var logOut = el('button', 'cafe-set-button', 'Log out')
		logOut.type = 'button'
		logOut.addEventListener('click', function () {
			close()
			CAFE.confirmLogout()
		})
		box.appendChild(accountRow('Log out', 'Sign out of your account on this device.', logOut))
		var remove = el('button', 'cafe-set-button danger', 'Delete account')
		remove.type = 'button'
		remove.disabled = true
		box.appendChild(
			accountRow('Delete account', 'Temporarily unavailable. Contact support if you need this.', remove)
		)
		return box
	}

	function buildPublicationsPanel() {
		var panel = el('div', 'cafe-saved-panel')
		var loading = el('div', 'cafe-loading')
		loading.hidden = true
		for (var i = 0; i < 4; i++) loading.appendChild(el('div', 'cafe-skeleton'))
		var empty = el('p', 'cafe-pub-mem-empty', "You're not part of any publications yet.")
		var failed = el('p', 'cafe-pub-mem-error', "Couldn't load your publications. Please try again.")
		empty.hidden = failed.hidden = true
		panel.appendChild(loading)
		panel.appendChild(empty)
		panel.appendChild(failed)
		panel.appendChild(el('div', 'cafe-pub-mem-list'))
		var create = el('button', 'cafe-set-button cafe-set-pub-create')
		create.type = 'button'
		create.appendChild(icon('plus'))
		create.appendChild(el('span', '', 'Create a new publication'))
		create.addEventListener('click', function () {
			openCreatePublication(panel)
		})
		panel.appendChild(create)
		return panel
	}

	function openDialog(tab) {
		if (dialog) return
		if (CAFE.closeNotifications) CAFE.closeNotifications()
		var user = currentUser()
		var opener = document.activeElement
		var overlay = el('div', 'cafe-overlay cafe-set-overlay')
		var modal = el('div', 'cafe-set-modal')
		modal.setAttribute('role', 'dialog')
		modal.setAttribute('aria-modal', 'true')
		modal.setAttribute('aria-label', 'Settings')
		modal.tabIndex = -1

		var side = el('div', 'cafe-set-side')
		side.appendChild(el('div', 'cafe-set-group', 'User settings'))
		var nav = el('div', 'cafe-set-nav')
		var navButtons = {}
		TABS.forEach(function (key) {
			var button = el('button', 'cafe-set-nav-item')
			button.type = 'button'
			if (key === 'account') {
				var avatar = el('span', 'cafe-set-avatar', (user.charAt(0) || '?').toUpperCase())
				button.appendChild(avatar)
			} else {
				button.appendChild(icon('newspaper'))
			}
			button.appendChild(el('span', 'cafe-set-nav-label', TITLES[key]))
			button.addEventListener('click', function () {
				select(key)
			})
			navButtons[key] = button
			nav.appendChild(button)
		})
		side.appendChild(nav)

		var content = el('div', 'cafe-set-content')
		var title = el('h2', 'cafe-set-title')
		var body = el('div', 'cafe-set-body')
		var accountPanel = buildAccount(close)
		var publicationsPanel = PUBLICATIONS_ENABLED ? buildPublicationsPanel() : null
		body.appendChild(accountPanel)
		if (publicationsPanel) body.appendChild(publicationsPanel)
		content.appendChild(title)
		content.appendChild(body)
		modal.appendChild(side)
		modal.appendChild(content)
		overlay.appendChild(modal)

		function select(key) {
			TABS.forEach(function (name) {
				var active = name === key
				navButtons[name].classList.toggle('active', active)
				if (active) navButtons[name].setAttribute('aria-current', 'true')
				else navButtons[name].removeAttribute('aria-current')
			})
			title.textContent = TITLES[key]
			accountPanel.hidden = key !== 'account'
			if (publicationsPanel) publicationsPanel.hidden = key !== 'publications'
			body.scrollTop = 0
			dialog.tab = key
			if (key === 'publications' && publicationsPanel) loadPublications(publicationsPanel)
		}

		function close() {
			if (!dialog) return
			document.removeEventListener('keydown', onKey)
			DESKTOP.removeEventListener('change', onResize)
			document.body.style.overflow = dialog.bodyOverflow
			overlay.remove()
			var tab = dialog.tab
			dialog = null
			if (opener && opener.focus && document.contains(opener)) opener.focus()
			return tab
		}
		function onKey(event) {
			if (event.key === 'Escape') {
				event.stopPropagation()
				close()
			}
		}
		// Below 768px Settings is a page, so a window that shrinks takes you there.
		function onResize(event) {
			if (event.matches) return
			close()
			location.assign('/settings')
		}

		dialog = { tab: tab, bodyOverflow: document.body.style.overflow }
		overlay.addEventListener('mousedown', function (event) {
			if (event.target === overlay) close()
		})
		document.addEventListener('keydown', onKey)
		DESKTOP.addEventListener('change', onResize)
		document.body.style.overflow = 'hidden'
		document.body.appendChild(overlay)
		select(tab)
		modal.focus()
	}
	CAFE.openSettings = function () {
		openDialog('account')
	}

	function setupDialogTriggers() {
		// The logo menu's Settings is a link (so it works without this script);
		// on a desktop it opens the dialog instead of leaving the page.
		document.addEventListener('click', function (event) {
			var link = event.target.closest('.cafe-menu a[href="/settings"]')
			if (!link || !DESKTOP.matches || event.ctrlKey || event.metaKey || event.shiftKey || event.button) return
			event.preventDefault()
			if (CAFE.closeMenu) CAFE.closeMenu()
			openDialog('account')
		})
		var wanted = new URLSearchParams(location.search).get('settings')
		if (TABS.indexOf(wanted) >= 0 && DESKTOP.matches) {
			var url = new URL(location.href)
			url.searchParams.delete('settings')
			history.replaceState(null, '', url)
			openDialog(wanted)
		}
	}

	document.addEventListener('DOMContentLoaded', function () {
		var root = document.getElementById('cafe-settings-page')
		if (!root) return setupDialogTriggers()
		// A desktop gets the dialog over the Home feed. The Builder editor's
		// Preview shows this page inside a frame: leave that one alone.
		// The Administrator stays: Builder draws the folder thumbnail as that user.
		if (DESKTOP.matches && window.top === window && !root.getAttribute('data-admin')) {
			var wantedTab = new URLSearchParams(location.search).get('tab')
			location.replace('/?settings=' + (TABS.indexOf(wantedTab) >= 0 ? wantedTab : 'account'))
			return
		}
		setupPage(root)
		// A phone that grows to desktop width gets the dialog too.
		DESKTOP.addEventListener('change', function (event) {
			if (event.matches && window.top === window)
				location.replace('/?settings=' + root.querySelector('[aria-selected="true"]').getAttribute('data-tab'))
		})
	})
})()
